import{_ as o,C as t,o as s,c as i,E as r,a2 as l}from"./chunks/framework.BOeh4kYD.js";const d="/joinwell52/assets/current-authority-20260911/result-delivery.figure.en.png",y=JSON.parse('{"title":"The Result Exists. Why Did the Agent Fail to Deliver It?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Result Exists. Why Did the Agent Fail to Deliver It?","date":"2026-09-11","published_date":"2026-09-11","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The Result Exists. Why Did the Agent Fail to Deliver It?","summary":"Ten original SDK regressions and a predecessor-helper ablation show why final text cannot prove complete result delivery.","cover":"/assets/current-authority-20260911/result-delivery.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source experiments; no real cloud validation","pageClass":"current-authority-article"},"headers":[],"relativePath":"en/engineering/2026-09-11-result-delivery.md","filePath":"en/engineering/2026-09-11-result-delivery.md","lastUpdated":1789097107000}'),c={name:"en/engineering/2026-09-11-result-delivery.md"};function p(h,e,u,m,g,f){const a=t("ArticleCover"),n=t("ArticleTableScroll");return s(),i("div",null,[r(a,{image:"/assets/current-authority-20260911/result-delivery.cover-v1.png",kicker:"Open-source Engineering · Experiments",title:"The Result Exists. Why Did the Agent Fail to Deliver It?",summary:"Ten original SDK regressions and a predecessor-helper ablation show why final text cannot prove complete result delivery.",version:"2026-09-11",languageHref:"/zh/engineering/2026-09-11-result-delivery",languageLabel:"中文"}),r(n,{language:"en"}),e[0]||(e[0]=l('<h1 id="the-result-exists-why-did-the-agent-fail-to-deliver-it" tabindex="-1">The Result Exists. Why Did the Agent Fail to Deliver It? <a class="header-anchor" href="#the-result-exists-why-did-the-agent-fail-to-deliver-it" aria-label="Permalink to &quot;The Result Exists. Why Did the Agent Fail to Deliver It?&quot;">​</a></h1><p>In a controlled resume experiment, the agent returned <code>done</code>. A check of the final text would have accepted the run. Inspecting the next model input revealed a missing tool result.</p><p>The result had already been produced before the interruption. It could even survive serialization with the run state. During recovery, however, its local existence was mistaken for prior delivery, so it was omitted from the next request.</p><p>We ran ten relevant upstream regressions against pinned OpenAI Agents SDK code. All passed with the fix. Replacing only the responsible helper with its predecessor made all ten fail. The experiment asks a practical question: when an agent produces a result, what evidence says the next participant received it?</p><h2 id="two-calls-one-approval-pause" tabindex="-1">Two calls, one approval pause <a class="header-anchor" href="#two-calls-one-approval-pause" aria-label="Permalink to &quot;Two calls, one approval pause&quot;">​</a></h2><p>The Agents SDK connects model responses, tool execution, and saved run state. A response may contain several tool calls, some requiring human approval—a human-in-the-loop, or HITL, interruption.</p><p><a href="https://github.com/openai/openai-agents-python/pull/4947" target="_blank" rel="noreferrer">Upstream fix #4947</a> concerns a mixed response: one call requires approval, while another names an unregistered tool. The runner produces a local error for the missing tool, then pauses for the other call. Under server-managed continuation, recovery could omit that error output.</p><p>An error output is still part of the conversation. It answers a particular call and tells the model that the requested operation did not run. Keeping an error in local state does not complete that handoff.</p><p>The approved tool may subsequently execute, and the model may produce plausible final text. Progress can therefore look normal while a different call remains unanswered in the prepared input.</p><h2 id="measure-the-next-input" tabindex="-1">Measure the next input <a class="header-anchor" href="#measure-the-next-input" aria-label="Permalink to &quot;Measure the next input&quot;">​</a></h2><p>We pinned commit <code>3f9397f035a891ce3623723eb0c2181847006fc9</code> and ran its ten added regressions with Python 3.12.10. The SDK runner, approval handling, serialization, recovery, and input preparation executed normally. The model was the upstream <code>ScriptedModel</code>, which emits predefined responses and records inputs. No real OpenAI service was called.</p><p>The comparison was a single-helper ablation, not a comparison of two complete releases. In a separate process, we replaced only the code of the helper that identifies unsent results with its implementation from <code>83c737fd0b8d9a53bd39fa2a0856070417bb0bd3</code>. All other SDK code and tests stayed identical.</p><table tabindex="0"><thead><tr><th>Original regression executed locally</th><th style="text-align:right;">Cases</th><th>Fixed implementation</th><th>Predecessor-helper ablation</th></tr></thead><tbody><tr><td>Two continuation modes × live/JSON state × streamed/non-streamed</td><td style="text-align:right;">8</td><td>All pass</td><td>Missing-tool output absent in all</td></tr><tr><td>Two staged approvals</td><td style="text-align:right;">1</td><td>Three outputs, each once</td><td>Missing-tool output absent</td></tr><tr><td>Interrupted state without a pending run for the missing tool</td><td style="text-align:right;">1</td><td>Unsent output preserved</td><td>Output incorrectly classified as delivered</td></tr></tbody></table><p>The eight-case matrix covers <code>conversation_id</code> and <code>auto_previous_response_id</code>. We did not separately run the complete Runner path with an explicitly supplied <code>previous_response_id</code>; the tracker-level case uses that field at a different observation boundary.</p><p>The failure location matters. In all eight matrix cases, the assertion that final output equals <code>done</code> had already passed. Only the later assertion over delivered call IDs detected the missing <code>call-missing</code>. Correct final text was insufficient evidence of complete handoff.</p><p><img src="'+d+'" alt="Result pairing under the fixed implementation and predecessor-helper ablation"></p><p><em>Figure 1. Result pairing in the controlled experiment. Source: this study&#39;s runs/sdk.json and ScriptedModel inputs; not acknowledgements of consumption by a real service.</em></p><h2 id="persistence-does-not-decide-delivery-ownership" tabindex="-1">Persistence does not decide delivery ownership <a class="header-anchor" href="#persistence-does-not-decide-delivery-ownership" aria-label="Permalink to &quot;Persistence does not decide delivery ownership&quot;">​</a></h2><p>Recovery cannot simply resend every local item. A server-managed conversation may already own some items. The runner must separate those from local outputs still needing delivery.</p><p>The old helper inspected pending tool-run groups. A missing tool had already received a locally synthesized error and left no ordinary pending execution in those groups. Enumerating only pending work therefore missed an existing but unsent result. Serializing state did not restore the missing classification.</p><p>The fix draws candidate call IDs from the latest model response while retaining prior ownership checks. Our ablation supports that causal explanation: restoring the old helper alone brought back the missing call across the same test paths.</p><p>This case did not require a new delivery database. Existing response records contained the necessary facts. Before introducing another ledger, determine whether the current records can answer the ownership question correctly.</p><h2 id="where-once-actually-holds" tabindex="-1">Where “once” actually holds <a class="header-anchor" href="#where-once-actually-holds" aria-label="Permalink to &quot;Where “once” actually holds&quot;">​</a></h2><p>The staged-approval test approves one call, resumes into another interruption without a model request, then approves the second call. Its assertion requires each of the three outputs to appear once in the subsequent scripted-model input.</p><p>That is a useful recovery property. It does not establish general exactly-once delivery under network failure. We did not simulate a request reaching a server while its acknowledgement was lost, verify server persistence or consumption, or prove that an external tool effect occurred only once.</p><p>The experiment inspired by this fix leaves a more specific follow-up question: if the server accepted a request but its acknowledgement was lost, what evidence should recovery use to choose between resending and avoiding duplication? A next experiment could inject failure on the acknowledgement path and separately observe request construction, server records, and retries. Selecting an appropriate SDK or transport test boundary is part of that work; the present ScriptedModel results cannot answer it. This is an open experimental question, not a newly established SDK defect.</p><p><a href="https://github.com/paperclipai/paperclip/blob/4e08ff2365dcd563e4e960edb3cb2e879d47238f/doc/BOARD-API-KEY-AUDIT-BOUNDARY.md" target="_blank" rel="noreferrer">Paperclip&#39;s audit-boundary document</a> addresses a different boundary: database transactions cannot roll back external effects, and ambiguous acknowledgements require durable intent and idempotency handling. It is a useful comparison, not another property established by this experiment.</p><p>Produced, persisted, delivered, and consumed are distinct facts. An implementation may derive them from existing records rather than storing four new flags. It still needs to preserve the distinction.</p><h2 id="one-more-acceptance-check-for-resume" tabindex="-1">One more acceptance check for resume <a class="header-anchor" href="#one-more-acceptance-check-for-resume" aria-label="Permalink to &quot;One more acceptance check for resume&quot;">​</a></h2><p>Start with a small counterexample in your own runtime: one call waits for approval while another produces a local success or error. Save and restore the state, then inspect call/output pairing in the next actual input. Stage two approvals and check for premature requests or duplicate outputs.</p><p>For CodeFlowMu/FCoP, this is now an input to development review: first map existing task records, call IDs, and delivery records to these facts. This study did not establish a corresponding product defect or authorize a new ledger implementation.</p><p>Final text remains a useful output. A successful recovery also needs evidence that the results owed to the next step actually entered it.</p><p>The <a href="./../research/evidence/2026-09-11-current-authority">evidence package</a> contains reproduction steps, passing and failing observations, source pins, and limitations. Materials are maintained in the <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">research repository</a>.</p>',33))])}const w=o(c,[["render",p]]);export{y as __pageData,w as default};
